static inline void fzn_line_record_fzn_message_stored_held_set(situ_msg_t *msg, situ_view_t view, uint8_t value)
{
	if (!(situ_in_bounds(view, fzn_line_record_fzn_message_stored_held_offset(view), 1u))) {
		return;
	}
	((situ_base(view) + fzn_line_record_fzn_message_stored_held_offset(view)))[0u] = (uint8_t)value;
	situ_msg_touch(msg);
}
